package com.hbm.network.separator;
import api.hbm.redstoneoverradio.*;
import com.hbm.energy.*;
import com.hbm.multiblock.*;
import java.math.BigInteger;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
/** Source independent input/outputHE nodes, surveyed downstream capacity and20tick transfer log. */
public final class NetworkSeparatorEntity extends BlockEntity implements EnergyReceiver,EnergyProvider,SidedEnergyConnector,IRORValueProvider,IRORInteractive,MuffledMachine {
 public static final long MAX_LIMIT=10_000_000_000L;private static final BigInteger LONG_MAX=BigInteger.valueOf(Long.MAX_VALUE),LONG_MIN=BigInteger.valueOf(Long.MIN_VALUE);private BigInteger power=BigInteger.ZERO,deltaTracker=BigInteger.ZERO;public final BigInteger[] deltaTick=new BigInteger[20];public BigInteger deltaSecond=BigInteger.ZERO,configuredLimit=BigInteger.valueOf(1000),actualLimit=configuredLimit;public ConnectionPriority priority=ConnectionPriority.NORMAL;public boolean redstone,muffled,tilted;private PowerNode input,output;private Direction cachedDirection;
 public NetworkSeparatorEntity(BlockPos pos,BlockState state){super(NetworkSeparatorContent.ENTITY.get(),pos,state);java.util.Arrays.fill(deltaTick,BigInteger.ZERO);}
 public Direction direction(){return DummyableBlock.facing(getBlockState()).getCounterClockWise();}public BlockPos outputPosition(){return worldPosition.relative(direction());}public BlockPos inputPosition(){return worldPosition.relative(direction().getOpposite());}
 private void connect(ServerLevel server){var dir=direction();if(dir!=cachedDirection){disconnect();cachedDirection=dir;}var space=HbmEnergy.nodespace(server);if(input==null||input.isExpired()){var pos=inputPosition();input=new PowerNode(pos).setConnections(new NodeConnection(pos.relative(dir.getOpposite()),dir.getOpposite()));space.createNode(input);}if(output==null||output.isExpired()){var pos=outputPosition();output=new PowerNode(pos).setConnections(new NodeConnection(pos.relative(dir),dir));space.createNode(output);}if(input.hasValidNet())input.addReceiver(this);if(output.hasValidNet())output.addProvider(this);}
 public PowerNode nodeAt(BlockPos pos){return pos.equals(inputPosition())?input:pos.equals(outputPosition())?output:null;}
 public void tickServer(){if(!(level instanceof ServerLevel server))return;connect(server);actualLimit=configuredLimit;if(output!=null&&output.hasValidNet()){BigInteger demand=BigInteger.ZERO;for(var receiver:output.network().receivers()){if(receiver instanceof NetworkSeparatorEntity separator)demand=demand.add(separator.actualLimit);else demand=demand.add(receiver.getMaxPowerExact().subtract(receiver.getPowerExact()).min(receiver.getReceiverSpeedExact()));}if(demand.compareTo(actualLimit)<0)actualLimit=demand;}actualLimit=actualLimit.max(power);BigInteger total=deltaTick[0];for(int i=1;i<20;i++){total=total.add(deltaTick[i]);deltaTick[i-1]=deltaTick[i];}deltaTick[19]=deltaTracker;deltaTracker=BigInteger.ZERO;deltaSecond=total;var dir=direction();redstone=server.hasNeighborSignal(worldPosition)||server.hasNeighborSignal(worldPosition.relative(dir))||server.hasNeighborSignal(worldPosition.relative(dir.getOpposite()));setChanged();var packet=getUpdatePacket();for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<225)player.connection.send(packet);}
 public boolean bufferMismatch(){return configuredLimit.compareTo(actualLimit)<0;}@Override public long getReceiverSpeed(){return legacy(getReceiverSpeedExact());}@Override public BigInteger getReceiverSpeedExact(){return redstone||bufferMismatch()?BigInteger.ZERO:actualLimit;}@Override public long getProviderSpeed(){return legacy(getProviderSpeedExact());}@Override public BigInteger getProviderSpeedExact(){return redstone?BigInteger.ZERO:actualLimit;}
 @Override public long getPower(){return legacy(power);}@Override public BigInteger getPowerExact(){return power;}@Override public void setPower(long amount){setPowerExact(BigInteger.valueOf(amount));}@Override public void setPowerExact(BigInteger amount){power=amount;setChanged();}@Override public long getMaxPower(){return legacy(actualLimit);}@Override public BigInteger getMaxPowerExact(){return actualLimit;}@Override public ConnectionPriority getPriority(){return priority;}@Override public boolean canConnect(Direction side){return side!=null&&(side==direction()||side==direction().getOpposite());}@Override public boolean isLoaded(){return level!=null&&!isRemoved()&&level.hasChunkAt(worldPosition);}
 @Override public BigInteger transferPowerExact(BigInteger amount){if(amount.signum()<0)throw new IllegalArgumentException("Negative HE transfer");var accepted=amount.min(actualLimit.subtract(power).max(BigInteger.ZERO));setPowerExact(power.add(accepted));return amount.subtract(accepted);}@Override public long transferPower(long amount){return transferPowerExact(BigInteger.valueOf(amount)).longValueExact();}@Override public void usePower(long amount){usePowerExact(BigInteger.valueOf(amount));}@Override public void usePowerExact(BigInteger amount){if(amount.signum()<0||amount.compareTo(power)>0)throw new IllegalArgumentException("Unavailable HE requested");setPowerExact(power.subtract(amount));deltaTracker=deltaTracker.add(amount);}
 public boolean hasPermission(Player player){return player.distanceToSqr(worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5)<=128;}private static ConnectionPriority safePriority(int n){return ConnectionPriority.values()[Math.abs(n%ConnectionPriority.values().length)];}
 public void control(CompoundTag tag){if(tag.contains("limit"))configuredLimit=BigInteger.valueOf(tag.getLong("limit"));if(tag.contains("priority"))priority=safePriority(tag.getByte("priority"));configuredLimit=configuredLimit.max(BigInteger.ZERO).min(BigInteger.valueOf(MAX_LIMIT));setChanged();}
 @Override public String[] getFunctionInfo(){return new String[]{PREFIX_VALUE+"deltatick",PREFIX_VALUE+"deltasecond",PREFIX_FUNCTION+"setpriority"+NAME_SEPARATOR+"priority (0-2)",PREFIX_FUNCTION+"setlimit"+NAME_SEPARATOR+"limit"};}@Override public String provideRORValue(String name){if((PREFIX_VALUE+"deltatick").equals(name))return deltaTick[19].toString();if((PREFIX_VALUE+"deltasecond").equals(name))return deltaSecond.toString();return null;}@Override public String runRORFunction(String name,String[] params){if((PREFIX_FUNCTION+"setpriority").equals(name)&&params.length>0){priority=safePriority(IRORInteractive.parseInt(params[0],0,2)+1);setChanged();return null;}if((PREFIX_FUNCTION+"setlimit").equals(name)&&params.length>0){configuredLimit=BigInteger.valueOf(IRORInteractive.parseLong(params[0],0,MAX_LIMIT));setChanged();return null;}return null;}
 private static long legacy(BigInteger value){return value.max(LONG_MIN).min(LONG_MAX).longValue();}private static BigInteger number(CompoundTag tag,String key){return tag.contains(key,8)?new BigInteger(tag.getString(key)):BigInteger.valueOf(tag.getLong(key));}
 private void read(CompoundTag tag){power=number(tag,"power");configuredLimit=number(tag,"configuredLimit");actualLimit=number(tag,"actualLimit");priority=safePriority(tag.getByte("p"));muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");if(tag.contains("hbm_redstone"))redstone=tag.getBoolean("hbm_redstone");if(tag.contains("hbm_delta_tick"))deltaTick[19]=number(tag,"hbm_delta_tick");if(tag.contains("hbm_delta_second"))deltaSecond=number(tag,"hbm_delta_second");}
 private CompoundTag write(CompoundTag tag){tag.putString("power",power.toString());tag.putString("configuredLimit",configuredLimit.toString());tag.putString("actualLimit",actualLimit.toString());tag.putByte("p",(byte)priority.ordinal());tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);return tag;}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);write(tag);}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);read(tag);}@Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=write(new CompoundTag());tag.putBoolean("hbm_redstone",redstone);tag.putString("hbm_delta_tick",deltaTick[19].toString());tag.putString("hbm_delta_second",deltaSecond.toString());return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){read(tag);}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection c,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){read(packet.getTag());}
 private void disconnect(){if(level instanceof ServerLevel server){var space=HbmEnergy.nodespace(server);if(input!=null&&!input.isExpired())space.destroyNode(input);if(output!=null&&!output.isExpired())space.destroyNode(output);}input=null;output=null;}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;}
}
